CREATE TABLE IF NOT EXISTS nicar."CuotaCredito" (
  "IdCuotaCredito" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "IdCredito" integer NOT NULL REFERENCES nicar."Credito"("IdCredito"),
  "NumeroCuota" smallint NOT NULL CHECK ("NumeroCuota" > 0),
  "FechaVencimiento" date NOT NULL,
  "CapitalUSD" numeric(12,2) NOT NULL CHECK ("CapitalUSD" >= 0),
  "InteresUSD" numeric(12,2) NOT NULL CHECK ("InteresUSD" >= 0),
  "CargosUSD" numeric(12,2) NOT NULL DEFAULT 0 CHECK ("CargosUSD" >= 0),
  "MontoProgramadoUSD" numeric(12,2) NOT NULL CHECK ("MontoProgramadoUSD" > 0),
  "MontoPagadoUSD" numeric(12,2) NOT NULL DEFAULT 0 CHECK ("MontoPagadoUSD" >= 0),
  "Estado" varchar(20) NOT NULL DEFAULT 'Pendiente'
    CHECK ("Estado" IN ('Pendiente', 'Parcial', 'Pagada', 'Vencida')),
  UNIQUE ("IdCredito", "NumeroCuota"),
  CHECK ("MontoPagadoUSD" <= "MontoProgramadoUSD")
);
CREATE INDEX IF NOT EXISTS "CuotaCredito_Vencimiento_idx"
  ON nicar."CuotaCredito" ("IdCredito", "FechaVencimiento");

CREATE TABLE IF NOT EXISTS nicar."ContratoVenta" (
  "IdContratoVenta" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "IdVenta" integer NOT NULL UNIQUE REFERENCES nicar."Venta"("IdVenta"),
  "NumeroContrato" varchar(80) NOT NULL UNIQUE,
  "FechaFirma" date NOT NULL,
  "Estado" varchar(20) NOT NULL DEFAULT 'Borrador'
    CHECK ("Estado" IN ('Borrador', 'Firmado', 'Anulado')),
  "DocumentoUrl" varchar(500),
  "Observaciones" varchar(500),
  "RegistradoPor" integer NOT NULL REFERENCES nicar."Usuario"("IdUsuario"),
  "FechaRegistro" timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE IF NOT EXISTS nicar."PagoVenta" (
  "IdPagoVenta" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "IdVenta" integer NOT NULL REFERENCES nicar."Venta"("IdVenta"),
  "NumeroPago" smallint NOT NULL DEFAULT 1 CHECK ("NumeroPago" > 0),
  "FechaPago" date NOT NULL,
  "MetodoPago" varchar(20) NOT NULL
    CHECK ("MetodoPago" IN ('Efectivo', 'Transferencia', 'Tarjeta', 'Cheque')),
  "Moneda" varchar(3) NOT NULL CHECK ("Moneda" IN ('USD', 'NIO')),
  "Monto" numeric(12,2) NOT NULL CHECK ("Monto" > 0),
  "TasaCambio" numeric(12,6) NOT NULL DEFAULT 36.60 CHECK ("TasaCambio" > 0),
  "Referencia" varchar(100),
  "Estado" varchar(20) NOT NULL DEFAULT 'Registrado'
    CHECK ("Estado" IN ('Registrado', 'Anulado')),
  "RegistradoPor" integer NOT NULL REFERENCES nicar."Usuario"("IdUsuario"),
  "FechaRegistro" timestamptz NOT NULL DEFAULT now(),
  UNIQUE ("IdVenta", "NumeroPago"),
  CHECK ("MetodoPago" = 'Efectivo' OR NULLIF(btrim("Referencia"), '') IS NOT NULL)
);

CREATE INDEX IF NOT EXISTS "PagoVenta_Fecha_idx"
  ON nicar."PagoVenta" ("FechaPago", "IdVenta");

REVOKE ALL ON nicar."CuotaCredito", nicar."ContratoVenta", nicar."PagoVenta"
  FROM PUBLIC, anon, authenticated;
GRANT SELECT, INSERT, UPDATE, DELETE ON nicar."CuotaCredito", nicar."ContratoVenta", nicar."PagoVenta" TO postgres;
GRANT USAGE, SELECT ON ALL SEQUENCES IN SCHEMA nicar TO postgres;
